function degree(edges, node) {
  let count = 0;
  for (const [a, b] of edges) {
    if (a === node || b === node) count += 1;
  }
  return count;
}

function hasEdge(edges, a, b) {
  return edges.some(([x, y]) => (x === a && y === b) || (x === b && y === a));
}

function neighbors(edges, node) {
  const result = [];
  for (const [a, b] of edges) {
    if (a === node) result.push(b);
    else if (b === node) result.push(a);
  }
  return result.sort();
}

function nodeCount(edges) {
  const seen = new Set();
  for (const [a, b] of edges) {
    seen.add(a);
    seen.add(b);
  }
  return seen.size;
}

function totalWeight(edges) {
  let total = 0;
  for (const [, , minutes] of edges) total += minutes;
  return total;
}

function outDegree(edges, node) {
  return edges.filter(([from]) => from === node).length;
}

function hasSelfLoop(edges) {
  return edges.some(([from, to]) => from === to);
}

function isSink(edges, node) {
  return !edges.some(([from]) => from === node);
}

function canStartAll(deps) {
  const state = {};
  function visit(name) {
    state[name] = "open";
    for (const next of deps[name] || []) {
      if (state[next] === "open") return false;
      if (state[next] === undefined && !visit(next)) return false;
    }
    state[name] = "done";
    return true;
  }
  for (const name of Object.keys(deps)) {
    if (state[name] === undefined && !visit(name)) return false;
  }
  return true;
}

function hopCount(edges, start, end) {
  const adj = {};
  for (const [a, b] of edges) {
    (adj[a] = adj[a] || []).push(b);
    (adj[b] = adj[b] || []).push(a);
  }
  const dist = { [start]: 0 };
  const queue = [start];
  while (queue.length > 0) {
    const current = queue.shift();
    if (current === end) return dist[current];
    for (const next of adj[current] || []) {
      if (dist[next] === undefined) {
        dist[next] = dist[current] + 1;
        queue.push(next);
      }
    }
  }
  return -1;
}

function reachableCount(deps, start) {
  const seen = new Set([start]);
  const stack = [start];
  while (stack.length > 0) {
    const current = stack.pop();
    for (const next of deps[current] || []) {
      if (!seen.has(next)) {
        seen.add(next);
        stack.push(next);
      }
    }
  }
  return seen.size;
}

function hasUndirectedCycle(edges) {
  const parent = {};
  function find(x) {
    if (parent[x] === undefined) parent[x] = x;
    while (parent[x] !== x) x = parent[x];
    return x;
  }
  for (const [a, b] of edges) {
    const rootA = find(a);
    const rootB = find(b);
    if (rootA === rootB) return true;
    parent[rootA] = rootB;
  }
  return false;
}
